import{_ as o,o as a,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"SMB Keeping - Clients, Clusters & Clouds - John Mulligan, IBM","description":"","frontmatter":{"title":"SMB Keeping - Clients, Clusters & Clouds - John Mulligan, IBM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","SMB","Cloud Storage","Distributed Storage","Storage Orchestration"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/SMB_Keeping_-_Clients_Clusters_Clouds_-_John_Mulligan_IBM.md","filePath":"posts/2025/SMB_Keeping_-_Clients_Clusters_Clouds_-_John_Mulligan_IBM.md","lastUpdated":1780459816000}'),r={name:"posts/2025/SMB_Keeping_-_Clients_Clusters_Clouds_-_John_Mulligan_IBM.md"};function i(n,e,s,h,d,g){return a(),t("div",null,[...e[0]||(e[0]=[l('<p>Ceph 会议纪要：SMB on Ceph 技术分享与讨论</p><h2 id="会议概览" tabindex="-1">会议概览 <a class="header-anchor" href="#会议概览" aria-label="Permalink to &quot;会议概览&quot;">​</a></h2><ul><li><strong>主题</strong>：SMB on Ceph 的技术进展、新特性及未来规划</li><li><strong>主讲人</strong>：John Mulligan（IBM 软件开发者，Samba 团队成员）</li><li><strong>核心内容</strong>：介绍了 SMB 协议在 Ceph 分布式存储生态中的集成，功能演示，2025年新特性，及社区合作展望。</li></ul><h2 id="背景与现状" tabindex="-1">背景与现状 <a class="header-anchor" href="#背景与现状" aria-label="Permalink to &quot;背景与现状&quot;">​</a></h2><h3 id="smb-on-ceph-的核心功能" tabindex="-1">SMB on Ceph 的核心功能 <a class="header-anchor" href="#smb-on-ceph-的核心功能" aria-label="Permalink to &quot;SMB on Ceph 的核心功能&quot;">​</a></h3><ul><li><strong>Ceph Manager Module</strong>：全局管理 SMB 相关配置，通过 <code>cephadm</code> 部署容器化组件。</li><li><strong>Active Directory (AD) 集成</strong>：基于 Windows 生态的身份管理与认证。</li><li><strong>CTDB 集群支持</strong>：通过 Samba 的 CTDB 工具实现高可用（HA）和容错性。</li><li><strong>VFS 模块优化</strong>：重构为 <code>VFS_new</code>，开发 <code>cephfs-proxy</code> 工具，提供 Samba 性能数据。</li><li><strong>监控与指标</strong>：通过 Prometheus 兼容的指标导出器提供 Samba 性能数据。</li></ul><h3 id="部署简易性" tabindex="-1">部署简易性 <a class="header-anchor" href="#部署简易性" aria-label="Permalink to &quot;部署简易性&quot;">​</a></h3><ul><li><strong>两步创建集群</strong>：支持 AD 和 CTDB 的快速部署。</li><li><strong>分层架构</strong>：命令式 CLI 与声明式接口，Sidecar 容器模型。</li></ul><h2 id="_2025年新特性" tabindex="-1">2025年新特性 <a class="header-anchor" href="#_2025年新特性" aria-label="Permalink to &quot;2025年新特性&quot;">​</a></h2><h3 id="collocation-多租户资源优化" tabindex="-1">Collocation（多租户资源优化） <a class="header-anchor" href="#collocation-多租户资源优化" aria-label="Permalink to &quot;Collocation（多租户资源优化）&quot;">​</a></h3><ul><li><strong>需求</strong>：同一 Ceph 节点上运行多个独立 SMB 实例。</li><li><strong>实现方式</strong>：端口隔离和 IP 隔离。</li></ul><h3 id="remote-control-精细化控制" tabindex="-1">Remote Control（精细化控制） <a class="header-anchor" href="#remote-control-精细化控制" aria-label="Permalink to &quot;Remote Control（精细化控制）&quot;">​</a></h3><ul><li><strong>功能</strong>：基于 gRPC 的 API，支持查询客户端连接状态，强制断开指定客户端。</li></ul><h3 id="qos-与速率限制" tabindex="-1">QoS 与速率限制 <a class="header-anchor" href="#qos-与速率限制" aria-label="Permalink to &quot;QoS 与速率限制&quot;">​</a></h3><ul><li><strong>目标</strong>：防止单一客户端占用过多带宽或 IOPS。</li><li><strong>配置项</strong>：带宽/IOPS 阈值，异步操作延迟调控。</li></ul><h3 id="fs-crypt-与-keybridge-多租户安全" tabindex="-1">FS-Crypt 与 Keybridge（多租户安全） <a class="header-anchor" href="#fs-crypt-与-keybridge-多租户安全" aria-label="Permalink to &quot;FS-Crypt 与 Keybridge（多租户安全）&quot;">​</a></h3><ul><li><strong>FS-Crypt</strong>：基于内核加密的 CephFS 用户空间 API。</li><li><strong>Keybridge</strong>：通用 KMS 连接器，通过 varlink RPC 与 SMBD 交互。</li></ul><h2 id="演示环节" tabindex="-1">演示环节 <a class="header-anchor" href="#演示环节" aria-label="Permalink to &quot;演示环节&quot;">​</a></h2><ul><li><strong>快速搭建集群</strong>：通过 <code>ceph smb cluster create</code> 和 <code>ceph smb share create</code> 命令。</li><li><strong>跨节点共享验证</strong>：Windows 客户端通过不同节点 IP 访问同一共享目录。</li><li><strong>Remote Control 演示</strong>：通过 gRPC API 动态断开指定客户端连接。</li></ul><h2 id="未来规划-2026" tabindex="-1">未来规划（2026） <a class="header-anchor" href="#未来规划-2026" aria-label="Permalink to &quot;未来规划（2026）&quot;">​</a></h2><ul><li><strong>社区协作</strong>：鼓励用户反馈需求，如多协议支持、ID 映射模式扩展。</li><li><strong>潜在方向</strong>：网络命名空间隔离，NFS/SMB 多协议并行访问。</li></ul><h2 id="q-a-重点摘要" tabindex="-1">Q&amp;A 重点摘要 <a class="header-anchor" href="#q-a-重点摘要" aria-label="Permalink to &quot;Q&amp;A 重点摘要&quot;">​</a></h2><ul><li><strong>多租户网络隔离</strong>：当前仅通过子网绑定隔离，未来可能支持网络命名空间。</li><li><strong>Windows ACL 支持</strong>：支持完整 ACL，当前默认 ID 映射模式为 <code>auto_rid</code>。</li><li><strong>NFS/SMB 同时访问</strong>：暂不支持，需解决子卷“earmarking”限制。</li><li><strong>Ceph CSI 集成</strong>：声明式 API 已通过 GObject 暴露，便于云编排工具调用。</li></ul><h2 id="后续行动项" tabindex="-1">后续行动项 <a class="header-anchor" href="#后续行动项" aria-label="Permalink to &quot;后续行动项&quot;">​</a></h2><ul><li><strong>功能完善</strong>：推进 FS-Crypt 和 QoS 的补丁合并，评估网络命名空间对多租户的增强价值。</li><li><strong>社区参与</strong>：收集用户对 ID 映射模式的需求，开放议题讨论 NFS/SMB 多协议共存方案。</li></ul>',25)])])}const _=o(r,[["render",i]]);export{c as __pageData,_ as default};
